const menu = document.querySelector('.menu-toggle');
const nav = document.querySelector('header nav');
menu.addEventListener('click', () => { const open = nav.classList.toggle('open'); menu.setAttribute('aria-expanded', String(open)); menu.setAttribute('aria-label', open ? 'Fermer le menu' : 'Ouvrir le menu'); });
nav.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { nav.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); nav.querySelectorAll('a').forEach(x => x.classList.toggle('active', x === a)); }));
document.querySelectorAll('[data-filter]').forEach(button => button.addEventListener('click', () => { document.querySelectorAll('[data-filter]').forEach(b => { b.classList.toggle('selected', b === button); b.setAttribute('aria-pressed', String(b === button)); }); document.querySelectorAll('[data-category]').forEach(card => {card.hidden = button.dataset.filter !== 'all' && card.dataset.category !== button.dataset.filter;}); }));
const dialog = document.querySelector('#detail-dialog');
const content = document.querySelector('#dialog-content');
function openDialog(html) {content.innerHTML = html; if (!dialog.open) dialog.showModal(); document.body.style.overflow = 'hidden';}
document.querySelector('.close-dialog').addEventListener('click', () => dialog.close());
dialog.addEventListener('close', () => {document.body.style.overflow = '';});
dialog.addEventListener('click', e => {if(e.target === dialog){const r=dialog.getBoundingClientRect();if(e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom)dialog.close();}});
const courses = {
 affaires: {title:'Les fondamentaux de la pratique contractuelle', audience:'Juristes, entrepreneurs et responsables administratifs', points:['Identifier les éléments essentiels d’un contrat.','Organiser la lecture et l’analyse des clauses.','S’exercer à une rédaction claire et structurée.']},
 social: {title:'Maîtriser les relations de travail au quotidien', audience:'Responsables RH, managers et professionnels du droit', points:['Comprendre les étapes de la relation de travail.','Repérer les situations qui nécessitent une analyse juridique.','Structurer ses réflexes de documentation et de suivi.']},
 immobilier: {title:'Comprendre et sécuriser les opérations immobilières', audience:'Professionnels de l’immobilier, juristes et porteurs de projets', points:['Identifier les acteurs et les documents d’une opération.','Organiser les vérifications préalables.','Comprendre les principaux points d’attention contractuels.']}
};
document.querySelectorAll('[data-course]').forEach(button => button.addEventListener('click', () => {const c=courses[button.dataset.course];openDialog(`<div class="dialog-label">PARCOURS DE FORMATION</div><h2>${c.title}</h2><p><b>Pour qui ?</b><br>${c.audience}.</p><h3>Les objectifs du parcours</h3><ul>${c.points.map(p=>`<li>${p}</li>`).join('')}</ul><p>Le programme détaillé, les modalités, les dates et les tarifs seront précisés par le cabinet.</p><button class="button" id="course-contact">Préparer ma demande</button>`);document.querySelector('#course-contact').onclick = () => contactForm(c.title);}));
const articles = {
 formation:{title:'Comprendre le droit, c’est déjà mieux agir.',body:'<p>Dans un environnement professionnel en évolution, entretenir ses connaissances est une démarche essentielle. Une formation offre un temps pour prendre du recul, structurer ses acquis et confronter ses méthodes à de nouvelles situations.</p><h3>Relier les notions aux situations concrètes</h3><p>La pratique juridique mobilise autant la compréhension des concepts que la capacité à poser les bonnes questions. Étudier des cas, comparer des raisonnements et expliquer une démarche contribue à construire cette compétence.</p><h3>Faire de l’apprentissage une habitude</h3><p>Choisir un objectif précis, prendre des notes et revenir sur ses acquis après une formation permet de prolonger l’apprentissage. Le bénéfice se mesure dans la qualité des questions que l’on sait ensuite formuler.</p>'},
 contrat:{title:'Lire un contrat : les questions à se poser avant de s’engager',body:'<p>La lecture d’un contrat commence par une vue d’ensemble : quel est son objet, qui sont les parties et quels engagements le document décrit-il ?</p><h3>Adopter une lecture structurée</h3><p>Repérer les définitions, les obligations, les délais et les annexes aide à comprendre l’organisation du document. Relever les passages ambigus permet ensuite de préparer les questions à adresser à un professionnel.</p><h3>Prendre le temps de clarifier</h3><p>Un terme technique ou une clause peu claire mérite une explication. Cette méthode de lecture constitue un repère pédagogique ; l’analyse d’un engagement précis dépend du document et de sa situation.</p>'},
 veille:{title:'Construire une veille juridique utile à sa pratique',body:'<p>Une veille efficace commence par un périmètre précis. Il vaut mieux suivre quelques sujets liés à ses missions que collecter des informations sans objectif.</p><h3>Choisir et organiser ses sources</h3><p>Identifier les publications officielles pertinentes, noter les références et classer les informations par thème facilite leur consultation. La date et le contexte d’un document méritent une attention particulière.</p><h3>Transformer la lecture en apprentissage</h3><p>Résumer ce que l’on a compris, consigner les questions ouvertes et programmer un temps de revue rend la veille plus utile au quotidien.</p>'}
};
document.querySelectorAll('[data-article]').forEach(button => button.addEventListener('click',()=>{const a=articles[button.dataset.article];openDialog(`<div class="dialog-label">LE BLOG · REPÈRES & MÉTHODES</div><h2>${a.title}</h2>${a.body}`);}));
document.querySelector('#library-button').addEventListener('click',()=>openDialog('<div class="dialog-label">LA BIBLIOTHÈQUE LEX ASSOCIÉS</div><h2>Des ressources pour approfondir votre pratique.</h2><p>Retrouvez prochainement la sélection d’ouvrages et de publications du cabinet, leurs présentations et leurs conditions d’achat.</p><p>Le catalogue sera accessible dès la mise à disposition des premiers titres.</p>'));
function contactForm(subject='') {openDialog('<div class="dialog-label">VOTRE PROJET</div><h2>Préparons votre échange.</h2><p>Rédigez votre demande et copiez-la pour la transmettre au cabinet.</p><form id="request-form"><label for="request-name">Votre nom ou votre organisation</label><input id="request-name" required autocomplete="organization" maxlength="160"><label for="request-type">Votre besoin</label><select id="request-type"><option>Une formation individuelle</option><option>Une formation pour mon équipe</option><option>Un accompagnement juridique</option><option>Un ouvrage de la bibliothèque</option></select><label for="request-message">Votre message</label><textarea id="request-message" required maxlength="3000"></textarea><p class="form-note">Cette demande n’est pas envoyée. Vous pourrez la copier puis la transmettre par votre canal habituel.</p><button type="submit" class="button">Copier ma demande</button><p class="copy-status" role="status"></p></form>');document.querySelector('#request-message').value=subject ? 'Je souhaite obtenir des informations sur la formation « '+subject+' ».' : ''; document.querySelector('#request-form').addEventListener('submit',async e=>{e.preventDefault();const text='Demande à LEX ASSOCIÉS\n\nNom / organisation : '+document.querySelector('#request-name').value+'\nBesoin : '+document.querySelector('#request-type').value+'\n\n'+document.querySelector('#request-message').value;try{await navigator.clipboard.writeText(text);document.querySelector('.copy-status').textContent='Demande copiée. Vous pouvez maintenant la transmettre au cabinet.';}catch{document.querySelector('#request-message').value=text;document.querySelector('#request-message').select();document.querySelector('.copy-status').textContent='Sélectionnez et copiez le texte de votre demande.'}});}
document.querySelector('#contact-button').onclick = () => contactForm();
